def trapezoid(f, a, b, n):
    if not isinstance(n, int) or n < 1:
        raise ValueError("n must be a positive integer")
    h = (b-a)/n
    return h * (0.5*f(a) + sum(f(a+i*h) for i in range(1,n)) + 0.5*f(b))

def simpson(f, a, b, n):
    if not isinstance(n, int) or n < 2 or n % 2:
        raise ValueError("n must be positive and even")
    h = (b-a)/n
    weighted = sum((4 if i % 2 else 2)*f(a+i*h) for i in range(1,n))
    return h/3 * (f(a) + weighted + f(b))

print(round(trapezoid(lambda x: x*x, 0, 1, 2), 6))
print(round(simpson(lambda x: x**3, 0, 1, 2), 6))
